True def transform(grid):
    from collections import Counter

    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    foreground = max((color for color in counts if color != background), key=counts.get)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        cols = [c for c, value in enumerate(row) if value == foreground]
        if cols and len(cols) == cols[-1] - cols[0] + 1:
            for c in range(cols[-1] + 1, len(row)):
                if row[c] == background:
                    out[r][c] = 1
    return out
